/// <summary>
/// Server-side implementation that queries the database directly (used during Server render mode).
/// </summary>
public class ShipmentServerService(IDbContextFactory<ApplicationDbContext> factory) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        await using var db = await factory.CreateDbContextAsync();
        return await db.Shipments
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        await using var db = await factory.CreateDbContextAsync();
        var shipment = await db.Shipments
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<List<ShipmentDto>> GetShipmentsForCustomerAsync(string email)
    {
        await using var db = await factory.CreateDbContextAsync();
        return await db.Shipments
            .Where(s => s.CustomerEmail == email)
            .OrderByDescending(s => s.ShippedDate)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public async Task<bool> UpdateShipmentStatusAsync(int id, UpdateShipmentStatusRequest request)
    {
        await using var db = await factory.CreateDbContextAsync();
        var shipment = await db.Shipments.FindAsync(id);
        if (shipment is null) return false;

        shipment.Status = (Data.ShipmentStatus)(int)request.Status;
        if (request.Notes is not null) shipment.Notes = request.Notes;
        if (request.Status == Client.Models.ShipmentStatus.Delivered)
            shipment.ActualDelivery = DateTime.UtcNow;

        await db.SaveChangesAsync();
        return true;
    }

