@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2 class="mb-4">📦 Dispatcher Dashboard</h2>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient..."
               @bind="searchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-primary w-100" @onclick="LoadShipments">
            🔄 Refresh
        </button>
    </div>
</div>

@if (loading)
{
    <div class="text-center my-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Weight (kg)</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td><strong>@shipment.TrackingNumber</strong></td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td>@shipment.RecipientName</td>
                        <td>@shipment.WeightKg.ToString("F1")</td>
                        <td>
                            <span class="badge @shipment.StatusBadgeClass">@shipment.StatusDisplay</span>
                        </td>
                        <td>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</td>
                        <td>
                            <button class="btn btn-sm btn-outline-secondary" @onclick="() => OpenUpdateDialog(shipment)">
                                ✏️ Update
                            </button>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count of @shipments.Count shipments</p>
}

@if (editingShipment is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Update Shipment @editingShipment.TrackingNumber</h5>
                    <button type="button" class="btn-close" @onclick="CloseDialog"></button>
                </div>
                <div class="modal-body">
                    <div class="mb-3">
                        <label class="form-label">New Status</label>
                        <select class="form-select" @bind="newStatus">
                            @foreach (var status in Enum.GetValues<ShipmentStatus>())
                            {
                                <option value="@status">@status</option>
                            }
                        </select>
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Notes</label>
                        <textarea class="form-control" rows="3" @bind="newNotes"></textarea>
                    </div>
                    @if (updateError is not null)
                    {
                        <div class="alert alert-danger">@updateError</div>
                    }
                </div>
                <div class="modal-footer">
                    <button class="btn btn-secondary" @onclick="CloseDialog">Cancel</button>
                    <button class="btn btn-primary" @onclick="SaveStatusUpdate" disabled="@saving">
                        @(saving ? "Saving..." : "Save Changes")
                    </button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string? errorMessage;
    private string searchTerm = "";
    private string statusFilter = "";

    private ShipmentDto? editingShipment;
    private ShipmentStatus newStatus;
    private string newNotes = "";
    private bool saving;
    private string? updateError;

    private List<ShipmentDto> FilteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
        .Where(s => string.IsNullOrEmpty(searchTerm)
            || s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
            || s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
            || s.RecipientName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        errorMessage = null;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }

    private void OpenUpdateDialog(ShipmentDto shipment)
    {
        editingShipment = shipment;
        newStatus = shipment.Status;
        newNotes = shipment.Notes;
        updateError = null;
    }

    private void CloseDialog() => editingShipment = null;

    private async Task SaveStatusUpdate()
    {
        if (editingShipment is null) return;
        saving = true;
        updateError = null;
        try
        {
            var success = await ShipmentService.UpdateShipmentStatusAsync(editingShipment.Id, new UpdateShipmentStatusRequest
            {
                Status = newStatus,
                Notes = newNotes
            });
            if (success)
            {
                CloseDialog();
                await LoadShipments();
            }
            else
            {
                updateError = "Failed to update shipment.";
            }
        }
        catch (Exception ex)
        {
            updateError = $"Error: {ex.Message}";
        }
        finally
        {
            saving = false;
        }
    }
}

