+                    <button class="btn btn-primary" @onclick="SaveStatusUpdate" disabled="@saving">
+                        @(saving ? "Saving..." : "Save Changes")
+                    </button>
+                </div>
+            </div>
+        </div>
+    </div>
+}
+
+@code {
+    private List<ShipmentDto> shipments = [];
+    private bool loading = true;
+    private string? errorMessage;
+    private string searchTerm = "";
+    private string statusFilter = "";
+
+    private ShipmentDto? editingShipment;
+    private ShipmentStatus newStatus;
+    private string newNotes = "";
+    private bool saving;
+    private string? updateError;
+
+    private List<ShipmentDto> FilteredShipments => shipments
+        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
+        .Where(s => string.IsNullOrEmpty(searchTerm)
+            || s.TrackingNumber.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
+            || s.Destination.Contains(searchTerm, StringComparison.OrdinalIgnoreCase)
+            || s.RecipientName.Contains(searchTerm, StringComparison.OrdinalIgnoreCase))
+        .ToList();
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        loading = true;
+        errorMessage = null;
+        try
+        {
+            shipments = await ShipmentService.GetAllShipmentsAsync();
+        }
+        catch (Exception ex)
+        {
+            errorMessage = $"Failed to load shipments: {ex.Message}";
+        }
+        finally
+        {
+            loading = false;
+        }
+    }
+
+    private void OpenUpdateDialog(ShipmentDto shipment)
+    {
+        editingShipment = shipment;
+        newStatus = shipment.Status;
+        newNotes = shipment.Notes;
+        updateError = null;
+    }
+
+    private void CloseDialog() => editingShipment = null;
+
+    private async Task SaveStatusUpdate()
+    {
+        if (editingShipment is null) return;
+        saving = true;
+        updateError = null;
+        try
+        {
+            var success = await ShipmentService.UpdateShipmentStatusAsync(editingShipment.Id, new UpdateShipmentStatusRequest
+            {
+                Status = newStatus,
+                Notes = newNotes
+            });
+            if (success)
+            {
+                CloseDialog();
+                await LoadShipments();
+            }
+            else
+            {
+                updateError = "Failed to update shipment.";
+            }
+        }
+        catch (Exception ex)
+        {
+            updateError = $"Error: {ex.Message}";
+        }
+        finally
+        {
+            saving = false;
+        }
+    }
+}
