@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h2 class="mb-4">🔍 Track Your Shipment</h2>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control form-control-lg" placeholder="Enter tracking number (e.g., TRK-2026-00001)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="SearchShipment" disabled="@searching">
                @(searching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (notFound)
{
    <div class="alert alert-warning">
        <strong>Not Found</strong> — No shipment found with tracking number "<strong>@lastSearched</strong>". Please verify and try again.
    </div>
}
else if (shipment is not null)
{
    <div class="card shadow-sm">
        <div class="card-header bg-primary text-white">
            <h4 class="mb-0">Shipment @shipment.TrackingNumber</h4>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <h5>Shipment Details</h5>
                    <table class="table table-borderless">
                        <tr>
                            <td class="text-muted">Recipient</td>
                            <td><strong>@shipment.RecipientName</strong></td>
                        </tr>
                        <tr>
                            <td class="text-muted">Origin</td>
                            <td>@shipment.Origin</td>
                        </tr>
                        <tr>
                            <td class="text-muted">Destination</td>
                            <td>@shipment.Destination</td>
                        </tr>
                        <tr>
                            <td class="text-muted">Weight</td>
                            <td>@shipment.WeightKg.ToString("F1") kg</td>
                        </tr>
                    </table>
                </div>
                <div class="col-md-6">
                    <h5>Delivery Status</h5>
                    <table class="table table-borderless">
                        <tr>
                            <td class="text-muted">Status</td>
                            <td><span class="badge @shipment.StatusBadgeClass fs-6">@shipment.StatusDisplay</span></td>
                        </tr>
                        <tr>
                            <td class="text-muted">Shipped Date</td>
                            <td>@shipment.ShippedDate.ToString("MMM dd, yyyy")</td>
                        </tr>
                        <tr>
                            <td class="text-muted">Estimated Delivery</td>
                            <td><strong>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</strong></td>
                        </tr>
                        @if (shipment.ActualDelivery.HasValue)
                        {
                            <tr>
                                <td class="text-muted">Actual Delivery</td>
                                <td class="text-success"><strong>@shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</strong></td>
                            </tr>
                        }
                    </table>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(shipment.Notes))
            {
                <div class="alert alert-info mt-3">
                    <strong>Notes:</strong> @shipment.Notes
                </div>
            }

            <!-- Progress tracker -->
            <div class="mt-4">
                <h5>Shipment Progress</h5>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @ProgressBarClass" role="progressbar"
                         style="width: @ProgressPercent%"
                         aria-valuenow="@ProgressPercent" aria-valuemin="0" aria-valuemax="100">
                        @shipment.StatusDisplay
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string? lastSearched;
    private ShipmentDto? shipment;
    private bool searching;
    private bool notFound;

    private int ProgressPercent => shipment?.Status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Returned => 100,
        _ => 0
    };

    private string ProgressBarClass => shipment?.Status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Returned => "bg-danger",
        _ => "bg-primary progress-bar-striped progress-bar-animated"
    };

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;

        searching = true;
        notFound = false;
        shipment = null;
        lastSearched = trackingNumber.Trim();

        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(lastSearched);
            notFound = shipment is null;
        }
        catch
        {
            notFound = true;
        }
        finally
        {
            searching = false;
        }
    }
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using Microsoft.AspNetCore.Components.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@rendermode InteractiveAuto
@inject IShipmentService ShipmentService
@inject AuthenticationStateProvider AuthStateProvider

<PageTitle>My Shipments</PageTitle>

<h2 class="mb-4">📋 My Shipments</h2>

@if (loading)
{
    <div class="text-center my-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else if (shipments.Count == 0)
{
    <div class="alert alert-info">
        <strong>No shipments found.</strong> No shipments are associated with your account (@userEmail).
    </div>
}
else
{
    <div class="row mb-3">
        <div class="col-md-4">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@status">@status</option>
                }
            </select>
        </div>
        <div class="col-md-2">
            <button class="btn btn-outline-primary" @onclick="LoadShipments">🔄 Refresh</button>
        </div>
    </div>

    <div class="row">
        @foreach (var shipment in FilteredShipments)
        {
            <div class="col-md-6 mb-3">
                <div class="card h-100 shadow-sm">
                    <div class="card-body">
                        <div class="d-flex justify-content-between align-items-start">
                            <h5 class="card-title">@shipment.TrackingNumber</h5>
                            <span class="badge @shipment.StatusBadgeClass">@shipment.StatusDisplay</span>
                        </div>
                        <p class="card-text text-muted">@shipment.Origin → @shipment.Destination</p>
                        <ul class="list-unstyled">
                            <li><strong>Shipped:</strong> @shipment.ShippedDate.ToString("MMM dd, yyyy")</li>
                            <li><strong>Est. Delivery:</strong> @shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</li>
                            @if (shipment.ActualDelivery.HasValue)
                            {
                                <li class="text-success"><strong>Delivered:</strong> @shipment.ActualDelivery.Value.ToString("MMM dd, yyyy")</li>
                            }
                            <li><strong>Weight:</strong> @shipment.WeightKg.ToString("F1") kg</li>
                        </ul>
                        @if (!string.IsNullOrEmpty(shipment.Notes))
                        {
                            <small class="text-muted">📝 @shipment.Notes</small>
                        }
                    </div>
                </div>
            </div>
        }
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count of @shipments.Count shipments for @userEmail</p>
}

@code {
    private List<ShipmentDto> shipments = [];
    private bool loading = true;
    private string? errorMessage;
    private string? userEmail;
    private string statusFilter = "";

    private List<ShipmentDto> FilteredShipments => shipments
        .Where(s => string.IsNullOrEmpty(statusFilter) || s.Status.ToString() == statusFilter)
        .ToList();

    protected override async Task OnInitializedAsync()
    {
        var authState = await AuthStateProvider.GetAuthenticationStateAsync();
        userEmail = authState.User.Identity?.Name;
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        if (string.IsNullOrEmpty(userEmail)) return;
        loading = true;
        errorMessage = null;
        try
        {
            shipments = await ShipmentService.GetShipmentsForCustomerAsync(userEmail);
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load shipments: {ex.Message}";
        }
        finally
        {
            loading = false;
        }
    }
}

